Image *
ReadPNGImage(const ImageInfo *image_info, ExceptionInfo *exception)
{
  Image *image;
  FILE *file;
  size_t count;
  unsigned char signature[PNG_SIG_SIZE];
  MngInfo *mng_info;

  (void) exception;

  assert(image_info != (const ImageInfo *) NULL);
  assert(exception != (ExceptionInfo *) NULL);
  assert(image_info->signature == MagickSignature);

  if (image == (Image *) NULL)
    return (Image *) NULL;

  if ((file = fopen(image_info->filename, "rb")) == (FILE *) NULL)
    return (Image *) NULL;

  count = fread(signature, 1, PNG_SIG_SIZE, file);
  if (count != PNG_SIG_SIZE || memcmp(signature, PNG_SIG, PNG_SIG_SIZE) != 0)
  {
    fclose(file);
    ThrowReaderException(CorruptImageError, InvalidImageFormat);
  }

  mng_info = (MngInfo *) AcquireMagickMemory(sizeof(*mng_info));
  if (mng_info == (MngInfo *) NULL)
  {
    fclose(file);
    return (Image *) NULL;
  }

  (void) memset(mng_info, 0, sizeof(*mng_info));

  image = ReadPNGImageFromData(image_info, file, mng_info, exception);

  if (image == (Image *) NULL)
  {
    RelinquishMagickMemory(mng_info);
    fclose(file);
    return (Image *) NULL;
  }

  if (image->columns == 0 || image->rows == 0)
  {
    DestroyImage(image);
    RelinquishMagickMemory(mng_info);
    fclose(file);
    return (Image *) NULL;
  }

  if (image->colorspace == UndefinedColorspace)
    image->colorspace = sRGBColorspace;

  RelinquishMagickMemory(mng_info);
  fclose(file);
  return image;
}

Image *ReadPNGImage(const ImageInfo *image_info, ExceptionInfo *exception) {
  Image *image = NULL;
  FILE *file = NULL;
  MngInfo *mng_info = NULL;
  size_t length = MagickPathExtent;
  char filename[MagickPathExtent];

  (void) CopyMagickPath(filename, image_info->filename, MagickPathExtent);

  if (image_info == (ImageInfo *) NULL)
    ThrowReaderException(OptionsError, MissingImage);
  if (image == (Image *) NULL)
    image = (Image *) AcquirePixelCache(image_info, exception);
  else {
    image->filename = (char *) AcquireMagickMemory(length * sizeof(*image->filename));
    (void) CopyMagickString(image->filename, image_info->filename, length);
  }
  if (image->exception.status != 0)
    return (Image *) DeregisterPixelCache(image);

  file = fopen(image_info->filename, "rb");
  if (file == (FILE *) NULL)
    ThrowReaderException(CoderError, UnableToOpenFile);
  if (getc(file) != '\211')
    {
      fclose(file);
      ThrowReaderException(CoderError, InvalidImage);
    }
  if (getc(file) != 'P')
    {
      fclose(file);
      ThrowReaderException(CoderError, InvalidImage);
    }

  mng_info = (MngInfo *) AcquireMagickMemory(sizeof(*mng_info));
  if (mng_info == (MngInfo *) NULL)
    {
      fclose(file);
      ThrowReaderException(ResourceLimitError, MemoryAllocationFailed);
    }

  (void) ResetMagickMemory(mng_info, 0, sizeof(*mng_info));
  mng_info->file = file;
  mng_info->image = image;

  if (!ReadPNGImageData(mng_info, exception))
    {
      fclose(file);
      DestroyMagickMemory(mng_info);
      return (Image *) DeregisterPixelCache(image);
    }

  if (image->columns == 0 || image->rows == 0)
    {
      fclose(file);
      DestroyMagickMemory(mng_info);
      ThrowReaderException(CoderError, InvalidImage);
    }

  if (image->colorspace != UndefinedColorspace)
    (void) SetImageColorspace(image, sRGBColorspace, exception);

  (void) fclose(file);
  DestroyMagickMemory(mng_info);
  return image;
}

Image *
ReadPNGImage(const ImageInfo *image_info, ExceptionInfo *exception)
{
  Image *image;
  FILE *file;
  size_t length;
  unsigned char signature[PNGSIG_LENGTH];
  MngInfo *mng_info;

  assert(image_info != NULL);
  assert(exception != NULL);

  /* Open the image file */
  file = fopen(image_info->filename, "rb");
  if (file == NULL)
  {
    (void) ThrowMagickException(exception, GetMagickModule(), FileOpenError,
      "UnableToOpenFile", "%s", image_info->filename);
    return (Image *) NULL;
  }

  /* Check the PNG signature */
  length = fread(signature, 1, PNGSIG_LENGTH, file);
  if (length != PNGSIG_LENGTH)
  {
    (void) fclose(file);
    (void) ThrowMagickException(exception, GetMagickModule(), CorruptImageError,
      "NotAPNGFile", "%s", image_info->filename);
    return (Image *) NULL;
  }

  if (png_sig_cmp(signature, 0, 8))
  {
    (void) fclose(file);
    (void) ThrowMagickException(exception, GetMagickModule(), CorruptImageError,
      "NotAPNGFile", "%s", image_info->filename);
    return (Image *) NULL;
  }

  /* Allocate and initialize MngInfo structure */
  mng_info = (MngInfo *) AcquireMagickMemory(sizeof(*mng_info));
  if (mng_info == NULL)
  {
    (void) fclose(file);
    (void) ThrowMagickException(exception, GetMagickModule(), ResourceLimitError,
      "MemoryAllocationFailed", "%s", image_info->filename);
    return (Image *) NULL;
  }

  (void) memset(mng_info, 0, sizeof(*mng_info));

  /* Read the PNG image into the image structure */
  image = ReadPNGImageBody(image_info, file, mng_info, exception);
  if (image == NULL)
  {
    mng_info = DestroyMngInfo(mng_info);
    (void) fclose(file);
    return (Image *) NULL;
  }

  /* Check image dimensions and adjust colorspace if necessary */
  if (image->columns < 1 || image->rows < 1)
  {
    (void) fclose(file);
    (void) ThrowMagickException(exception, GetMagickModule(), CorruptImageError,
      "InvalidImageGeometry", "%s", image_info->filename);
    image = DestroyImageList(image);
    return (Image *) NULL;
  }

  if (image->colorspace == UndefinedColorspace)
    (void) SetImageColorspace(image, sRGBColorspace, exception);

  (void) fclose(file);
  return image;
}

Image *ReadPNGImage(const ImageInfo *image_info, ExceptionInfo *exception) {
    Image *image = NULL;
    FILE *file = NULL;

    if ((image_info == NULL) || (exception == NULL))
        return NULL;

    LogMagickEvent(CoderEvent, "Entering ReadPNGImage");

    file = fopen(image_info->filename, "rb");
    if (file == NULL) {
        ThrowFileException(exception, FileOpenError, image_info->filename, image_info->filename);
        goto cleanup;
    }

    // Check PNG signature
    uint8_t signature[8];
    if (fread(signature, 1, 8, file) != 8) {
        ThrowFileException(exception, CorruptImageError, "ImproperPNGFileSignature", image_info->filename);
        goto cleanup;
    }

    if (memcmp(signature, "\211PNG\r\n\032\n", 8) != 0) {
        ThrowFileException(exception, CorruptImageError, "ImproperPNGFileSignature", image_info->filename);
        goto cleanup;
    }

    // Allocate MngInfo structure
    MngInfo *mng_info = (MngInfo *) AcquireMagickMemory(sizeof(*mng_info));
    if (mng_info == NULL) {
        ThrowMagickException(exception, MagickResourceLimit, "MemoryAllocationFailed", 0, "Unable to allocate MngInfo structure");
        goto cleanup;
    }

    (void) memset(mng_info, 0, sizeof(*mng_info));

    // Read PNG image data into image
    image = (Image *) AcquireMagickMemory(sizeof(*image));
    if (image == NULL) {
        ThrowMagickException(exception, MagickResourceLimit, "MemoryAllocationFailed", 0, "Unable to allocate Image structure");
        goto cleanup;
    }

    (void) memset(image, 0, sizeof(*image));
    GetImageInfo(image_info, image, exception);

    // Process PNG data, set image dimensions, colorspace, etc.
    // (Assumed to be handled by helper functions in PNG coder)

    // Example of colorspace adjustment
    if ((image->colorspace != RGBColorspace) && (image->colorspace != GrayColorspace)) {
        image->colorspace = RGBColorspace;
        (void) SetImageColorspace(image, RGBColorspace, exception);
    }

    LogMagickEvent(CoderEvent, "Exiting ReadPNGImage");

cleanup:
    if (file != NULL)
        fclose(file);
    if (mng_info != NULL)
        mng_info = (MngInfo *) RelinquishMagickMemory(mng_info);

    return image;
}

Image *
ReadPNGImage(const ImageInfo *image_info, ExceptionInfo *exception)
{
    Image *image = NULL;
    FILE *file = NULL;
    unsigned char signature[PNG_SIG_SIZE];

    assert(image_info != NULL);
    assert(exception != NULL);

    /* Open the image file */
    file = fopen(image_info->filename, "rb");
    if (!file) {
        (void) ThrowMagickException(exception, GetMagickModule(), FileOpenError,
                                    "Unable to open file", "%s", image_info->filename);
        return NULL;
    }

    /* Check for valid PNG signature */
    if (fread(signature, 1, PNG_SIG_SIZE, file) != PNG_SIG_SIZE) {
        (void) fclose(file);
        (void) ThrowMagickException(exception, GetMagickModule(), CorruptImageError,
                                    "Invalid PNG signature", "%s", image_info->filename);
        return NULL;
    }

    if (png_sig_cmp(signature, 0, PNG_SIG_SIZE)) {
        (void) fclose(file);
        (void) ThrowMagickException(exception, GetMagickModule(), CorruptImageError,
                                    "Invalid PNG signature", "%s", image_info->filename);
        return NULL;
    }

    /* Allocate MngInfo structure */
    MngInfo *mng_info = AcquireMngInfo(image_info, exception);
    if (!mng_info) {
        (void) fclose(file);
        return NULL;
    }

    /* Read PNG data into Image structure */
    image = ReadPNGImageInternal(file, image_info, mng_info, exception);
    if (!image) {
        (void) fclose(file);
        DestroyMngInfo(mng_info);
        return NULL;
    }

    (void) fclose(file);

    /* Adjust colorspace if needed */
    if (image->colorspace == UndefinedColorspace)
        image->colorspace = sRGBColorspace;

    if (image->depth != 8)
        image->depth = 8;

    return image;
}
